  (1, 3, 3, '{"prompt":"Which mini-story stays in the past?","choices":["The witch waved her wand. Then she turn into a black cat.","The witch waves her wand. Then she turned into a black cat.","The witch waved her wand. Then she turned into a black cat.","The witch waved her wand. Then she turns into a black cat."],"answer":2,"picture":"black-cat"}'),
