-- ============================ PART 2: APPLY ================================
-- Only run this after you checked the rows from PART 1.
-- It runs as one all-or-nothing step: either every change happens, or none.

begin;

-- Test week · Grade 4
do $$ begin if not exists (select 1 from wp_classes where grade = 4) then
  raise exception 'No class for grade 4: import the roster first'; end if; end $$;
insert into wp_plans (title, kind) values ('Test week · Grade 4', 'test') on conflict (title) do update set kind = excluded.kind;
insert into wp_plan_assignments (plan_id, class_id)
  select (select id from wp_plans where title = 'Test week · Grade 4'), (select id from wp_classes where grade = 4 order by name, id limit 1) where not exists (select 1 from wp_plan_assignments where plan_id = (select id from wp_plans where title = 'Test week · Grade 4') and class_id = (select id from wp_classes where grade = 4 order by name, id limit 1));
insert into wp_weeks (plan_id, position, skill, opens_on) values ((select id from wp_plans where title = 'Test week · Grade 4'), 1, 'Past tense in stories', '2026-11-26')
  on conflict (plan_id, position) do nothing;
insert into wp_lessons (week_id, position, title) values ((select id from wp_weeks where plan_id = (select id from wp_plans where title = 'Test week · Grade 4') and position = 1), 1, 'Yesterday with -ed')
  on conflict (week_id, position) do nothing;
update wp_questions set type = 'pick_one', payload = '{"prompt":"One of these is right. Tap it.","choices":["Nova droped her spoon and picked it up.","Nova drop her spoon and picked it up.","Nova dropped her spoon and pick it up.","Nova dropped her spoon and picked it up."],"answer":3,"picture":"spoon"}'::jsonb, skill = 'past-tense', updated_at = now()
