  and (type <> 'pick_one' or payload <> '{"prompt":"One of these is right. Tap it.","choices":["Nova droped her spoon and picked it up.","Nova drop her spoon and picked it up.","Nova dropped her spoon and pick it up.","Nova dropped her spoon and picked it up."],"answer":3,"picture":"spoon"}'::jsonb or skill is distinct from 'past-tense');
